CREATE TRIGGER rev_submission_rebuts_opposing_points_upd AFTER UPDATE ON submission_rebuts_opposing_points BEGIN UPDATE db_meta SET value = CAST(value AS INTEGER) + 1 WHERE key = 'revision'; END;

